 async function access(){const v=visit;const gate=await window.ErpRuntimeGuard.requireUser(client,{redirectUrl:'index.html',alertFn:m=>{if(v===visit)text('pageStatus',m);}});if(v!==visit)throw Error('화면이 바뀌었습니다. 현재 화면에서 다시 확인해 주세요.');if(!gate.ok){deactivate('로그인을 확인해 주세요.');throw Error('로그인을 확인해 주세요.');}const result=await window.ErpRuntimeGuard.enforce(client,{moduleKey:'member_admin',moduleLabel:'등기 업무',redirectUrl:'index.html',alertFn:m=>{if(v===visit)text('pageStatus',m);}});if(v!==visit)throw Error('화면이 바뀌었습니다. 현재 화면에서 다시 확인해 주세요.');if(!result.ok||!M.access(result.runtime)){deactivate('조합원 관리 권한과 조합 연결을 확인해 주세요.');throw Error('조합원 관리 권한과 조합 연결을 확인해 주세요.');}const auth=gate.authUser?.id;if(!auth)throw Error('로그인 주체를 확인하지 못했습니다.');if(owner&&(owner!==auth||coop!==result.runtime.coop_id)){deactivate('로그인 주체 또는 조합이 변경되었습니다.',true);throw Error('화면을 다시 열어 주세요.');}owner=auth;coop=result.runtime.coop_id;authorized=true;form.hidden=false;$('retryAccess').hidden=true;text('pageStatus','');return result.runtime;}
