 async function listApplicants(){if(busy||!authorized)return;const v=visit;text('applicantStatus','ERP 직원 목록을 확인하고 있습니다.');try{await read('applicants',async(op,current)=>{await access();if(!current())return;const r=await client.rpc('erp_list_approval_employees').select('emp_id,emp_name,position,department').abortSignal(op.controller.signal);if(!current())return;if(r.error||!Array.isArray(r.data)||r.data.some(e=>!e.emp_id||!e.emp_name)||new Set(r.data.map(e=>e.emp_id)).size!==r.data.length)throw Error('직원 목록을 확인하지 못했습니다. 직접 입력하거나 같은 버튼으로 다시 확인해 주세요.');employees=r.data;const old=$('applicantEmployee').value;$('applicantEmployee').replaceChildren(new Option('선택하지 않음 · 직접 입력',''),...employees.map(e=>new Option([e.emp_name,e.department,e.position].filter(Boolean).join(' · '),e.emp_id)));if(employees.some(e=>e.emp_id===old))$('applicantEmployee').value=old;else selectedApplicant=null;text('applicantStatus',employees.length?'신고할 직원을 선택하거나 직접 입력해 주세요.':'선택 가능한 직원이 없습니다. 신고인 정보를 직접 입력해 주세요.');});}catch(e){if(authorized&&visit===v&&visible())text('applicantStatus',e.message);}}
